		case "CharacterID":
			_datasource_Root.TroopID = _widget.CharacterID;
			break;
		case "IsMainHero":
			_datasource_Root.IsMainHero = _widget.IsMainHero;
			break;
		case "IsPrisoner":
			_datasource_Root.IsPrisoner = _widget.IsPrisoner;
			break;
		case "IsTransferable":
			_datasource_Root.IsTroopTransferrable = _widget.IsTransferable;
			break;
		case "TransferAmount":
			_datasource_Root.TransferAmount = _widget.TransferAmount;
			break;
		case "IsSelected":
			_datasource_Root.IsSelected = _widget.IsSelected;
			break;
		}
	}

